<?php
declare(strict_types=1);
// Audit ciblé : uniquement sur une base neuve explicitement réservée à cet audit.
$sourceRoot=getenv('BD70_AUDIT_ROOT')?:dirname(__DIR__,2);
require $sourceRoot.'/src/bootstrap.php';
$name=getenv('BD70_DATABASE');
if(!is_string($name)||!preg_match('/^bd70_test_audit_probes_[a-z0-9_]+$/',$name))die("Base dédiée d'audit requise.\n");
$db=new Database();$cat=new Catalog($db);$w=new Warehouse($db,1);$results=[];
function observe(string $key,callable $f):void{global $results;try{$results[$key]=$f();}catch(Throwable $e){$results[$key]=['exception'=>get_class($e),'message'=>$e->getMessage()];}}
observe('clock',fn()=>['php'=>date('Y-m-d H:i:s'),'timezone'=>date_default_timezone_get(),'sql'=>$db->one('SELECT NOW() now_sql,CURRENT_DATE() date_sql,@@session.time_zone tz')]);
observe('phone_edit_used_driver',function()use($db,$cat){$d=$db->one('SELECT * FROM driver WHERE id=1');$d['phone']='AUDIT-NEW-PHONE';return $cat->save('driver',1,$d,1);});
observe('renew_used_qualification',function()use($db,$cat){$d=$db->one('SELECT * FROM driver_qualification WHERE id=1');$d['expires_on']='2029-12-31';return $cat->save('driver_qualification',1,$d,1);});
observe('live_dock_during_php_appointment',function()use($db,$w){$start=date('Y-m-d H:i:s',time()-300);$end=date('Y-m-d H:i:s',time()+1500);$id=$w->appointment(['reference'=>'AUDIT-NOW','dock_id'=>1,'driver_id'=>1,'vehicle_id'=>1,'trailer_id'=>null,'operation'=>'reception','starts_at'=>$start,'ends_at'=>$end]);$r=new Reports($db);$before=$r->docks(date('Y-m-d'))[0]['live_state'];$old=$db->scalar('SELECT @@session.time_zone');try{$offset=(new DateTimeImmutable('now',new DateTimeZone('Europe/Paris')))->format('P');$db->run('SET time_zone=?',[$offset]);$after=$r->docks(date('Y-m-d'))[0]['live_state'];}finally{$db->run('SET time_zone=?',[$old]);}return ['appointment'=>[$start,$end],'sql_system_zone'=>$before,'sql_paris_offset_for_this_test'=>$after,'session_setting_restored'=>true];});
observe('trailer_not_in_dock_types',function()use($db,$w){$dock=$db->insert('dock',['code'=>'AUDIT-TRACTOR','name'=>'Tracteur seulement','type'=>'mixte']);$db->insert('dock_vehicle_type',['dock_id'=>$dock,'vehicle_type'=>'tracteur']);$id=$w->appointment(['reference'=>'AUDIT-TRAILER','dock_id'=>$dock,'driver_id'=>1,'vehicle_id'=>3,'trailer_id'=>4,'operation'=>'reception','starts_at'=>'2027-02-02 08:00:00','ends_at'=>'2027-02-02 09:00:00']);return ['accepted'=>true,'appointment_id'=>$id,'allowed_types'=>['tracteur'],'trailer_type'=>'remorque'];});
observe('same_driver_vehicle_two_docks',function()use($w){$d=['reference'=>'AUDIT-DOUBLE-A','dock_id'=>1,'driver_id'=>1,'vehicle_id'=>1,'trailer_id'=>null,'operation'=>'reception','starts_at'=>'2027-02-03 08:00:00','ends_at'=>'2027-02-03 09:00:00'];return [$w->appointment($d),$w->appointment([...$d,'reference'=>'AUDIT-DOUBLE-B','dock_id'=>2])];});
observe('cancel_then_edit_order',function()use($db,$cat,$w){$o=$db->insert('customer_order',['reference'=>'AUDIT-CANCEL','owner_id'=>1,'destination'=>'Fictive','desired_on'=>'2027-02-02']);$db->insert('order_line',['order_id'=>$o,'article_id'=>1,'qty'=>1]);$w->prepare($o,4);$w->cancelOrder($o);$d=$db->one('SELECT * FROM customer_order WHERE id=?',[$o]);$d['destination']='Adresse corrigée';return $cat->save('customer_order',$o,$d,1);});
observe('split_pick_two_packages',function()use($db,$cat,$w){$o=$db->insert('customer_order',['reference'=>'AUDIT-SPLIT','owner_id'=>1,'destination'=>'Fictive','desired_on'=>'2027-02-02']);$db->insert('order_line',['order_id'=>$o,'article_id'=>1,'qty'=>2]);$w->prepare($o,4);$w->confirmPick($o,4,'warehouse');$p=$db->scalar('SELECT p.id FROM pick p JOIN order_line ol ON ol.id=p.order_line_id WHERE ol.order_id=?',[$o]);$a=$cat->save('package',null,['order_id'=>$o,'code'=>'AUDIT-PKG-A','type'=>'colis'],1);$b=$cat->save('package',null,['order_id'=>$o,'code'=>'AUDIT-PKG-B','type'=>'colis'],1);$cat->save('package_pick',null,['package_id'=>$a,'pick_id'=>$p],1);return $cat->save('package_pick',null,['package_id'=>$b,'pick_id'=>$p],1);});
observe('full_shortage_and_reserve',function()use($db,$cat,$w){$v=$w->arrive(['reference'=>'AUDIT-MISSING-IN','driver_id'=>2,'vehicle_id'=>2,'operation'=>'reception']);$w->transition($v,'checked',null,'Documents contrôlés');$w->transition($v,'called',2);$w->transition($v,'working');$n=$cat->save('supplier_notice',null,['reference'=>'AUDIT-MISSING-N','supplier_id'=>1,'expected_on'=>date('Y-m-d')],1);$nl=$cat->save('notice_line',null,['notice_id'=>$n,'article_id'=>1,'expected_qty'=>10],1);$r=$cat->save('receipt',null,['reference'=>'AUDIT-MISSING-R','notice_id'=>$n,'visit_id'=>$v],1);$rl=$cat->save('receipt_line',null,['receipt_id'=>$r,'notice_line_id'=>$nl,'expected_qty'=>10],1);$reserveAttempt='';try{$cat->save('receipt_item',null,['line_id'=>$rl,'lot_id'=>1,'pallet_code'=>'AUDIT-EMPTY','accepted_qty'=>0,'damaged_qty'=>0,'pallet_state'=>'bon','reservation'=>'10 unités absentes, réserve au transporteur','location_id'=>1],1);}catch(Throwable $e){$reserveAttempt=$e->getMessage();}$w->validateReceipt($r);return ['receipt'=>$db->one('SELECT status FROM receipt WHERE id=?',[$r]),'gap'=>$db->one('SELECT * FROM v_receipt_discrepancy WHERE receipt_id=?',[$r]),'zero_item_reserve_error'=>$reserveAttempt,'receipt_and_line_have_reservation'=>array_intersect(['reservation'],array_column($cat->columns('receipt'),'Field'),array_column($cat->columns('receipt_line'),'Field'))];});
observe('current_period_no_carriers',fn()=>count((new Reports($db))->dashboard(['from'=>'2040-01-01','to'=>'2040-01-01'])['carriers']));
observe('empty_chart_php',fn()=>max(1,...[]));
observe('audit_values',fn()=>$db->one("SELECT entity,operation,details FROM audit_log WHERE entity='customer_order' AND operation='UPDATE' ORDER BY id DESC LIMIT 1"));
observe('historic_dlc_current_sql_date',function()use($db){$old=$db->scalar('SELECT @@session.timestamp');try{$db->run('SET timestamp = UNIX_TIMESTAMP(?)',['2026-12-01 12:00:00']);$r=(new Reports($db))->dashboard(['from'=>'2026-10-22','to'=>'2026-10-22']);return ['simulated_sql_today'=>$db->scalar('SELECT CURRENT_DATE()'),'report_start'=>'2026-10-22','dlc'=>$r['dlc'],'expected_seed_cold_qty'=>40];}finally{$db->run('SET timestamp=0');}});
echo json_encode($results,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)."\n";
file_put_contents(__DIR__.'/preuves/audit-probes-reexecution.json',json_encode($results,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));
